import{_ as t,c as n,j as e,a as _,o as l}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百六十章 舍离放弃丰厚的供养","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/160第一百六十章 舍离放弃丰厚的供养.md","filePath":"meditation/巴利文大藏经/160第一百六十章 舍离放弃丰厚的供养.md"}'),r={name:"meditation/巴利文大藏经/160第一百六十章 舍离放弃丰厚的供养.md"};function o(s,a,i,d,p,c){return l(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百六十章-舍离放弃丰厚的供养",tabindex:"-1"},[_("第一百六十章 舍离放弃丰厚的供养 "),e("a",{class:"header-anchor",href:"#第一百六十章-舍离放弃丰厚的供养","aria-label":'Permalink to "第一百六十章 舍离放弃丰厚的供养"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"17.(6).利得恭敬相应",-1),e("p",null,"1.第一品",-1),e("p",null,"相应部17相应1经/恐畏经(利得恭敬相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望，这些是让人内心颤抖恐怖的，这些是让人内心激烈搅动的，这些是让人内心暴躁不安的，这些是修行人内心达到清净安稳的障碍，这些是修行人内心挣脱束缚捆绑的阻碍。弟子们，就是因为如此，所以你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
